#!/usr/bin/env bash
# Remove the "Generated by Claude Code" footer from PR descriptions and PR comments (uses your own gh login).
#   ./scripts/strip-pr-footer.sh          # every PR in the repo
#   ./scripts/strip-pr-footer.sh 19 20    # just these PRs
set -euo pipefail
cd "$(dirname "$0")/.."
REPO="$(gh repo view --json nameWithOwner -q .nameWithOwner)"
strip() { perl -0pe 's/\s*(---\s*)?_Generated by \[Claude Code\]\([^)]*\)_\s*\z/\n/'; }
# macOS bash 3.2: no mapfile, and empty arrays trip `set -u` — use a plain word list
PRS="$*"; [ -n "$PRS" ] || PRS="$(gh pr list -R "$REPO" --state all --limit 500 --json number -q '.[].number')"
n=0
for pr in $PRS; do
  body="$(gh pr view "$pr" -R "$REPO" --json body -q .body)"
  if grep -q 'Generated by \[Claude Code\]' <<<"$body"; then
    strip <<<"$body" > /tmp/pr-body.md && gh pr edit "$pr" -R "$REPO" --body-file /tmp/pr-body.md >/dev/null && n=$((n+1)) && echo "  #$pr description"
  fi
  while read -r id; do
    [ -n "$id" ] || continue
    gh api "repos/$REPO/issues/comments/$id" -q .body | strip > /tmp/pr-comment.md
    gh api -X PATCH "repos/$REPO/issues/comments/$id" -F body=@/tmp/pr-comment.md >/dev/null && n=$((n+1)) && echo "  #$pr comment $id"
  done < <(gh api "repos/$REPO/issues/$pr/comments" -q '.[] | select(.body | test("Generated by \\[Claude Code\\]")) | .id')
done
echo "✓ removed the footer from $n description(s)/comment(s)"
